import{_ as t,o as e,c as o,a5 as a}from"./chunks/framework.BPFk9-tb.js";const s="/assets/%E8%B5%84%E9%87%91%E6%B5%81%E5%90%91.BM4IGSbt.png",m=JSON.parse('{"title":"一个消费贷的故事","description":"","frontmatter":{"date":"2021-08-02T20:57:26","title":"一个消费贷的故事","categories":["定投课堂","金融"],"tags":["定投课堂","金融"]},"headers":[],"relativePath":"posts/finance/loan.md","filePath":"posts/finance/loan.md"}'),n={name:"posts/finance/loan.md"};function c(r,p,_,i,l,d){return e(),o("div",null,[...p[0]||(p[0]=[a('<blockquote><p>桑德拉还是学生时，曾参与了一项针对低收入家庭的“领先”儿童发展计划。现在，她在信函挪威小镇的“领先”项目理事会中负责管理工作。她被雇主北卡罗来纳大学威明顿分校评选为优秀员工，还在WMNX电台主持了一档广播节目，算是威明顿当地的名人。但光鲜的外表不能代表全部：她丈夫曾是一名行政厨师，最近却失业了；夫妻俩本来一直能提前一个月支付房租和各项账单，但现在手头却有些吃紧；他们的汽车保险眼看就要到期了，却没有续报。</p></blockquote><blockquote><p>后来，桑德拉想到了一个解决办法：申请工薪日贷款。这个贷款的理念很简单：先通过贷款拿到现金，几周后发薪水时，在偿还贷款，支付手续费。这正是她要的服务。他用贷款续了汽车保险。到了下一个发薪日时，桑德拉就有能力还清这笔小贷款，并支付50美元的手续费。</p><p>工薪日贷款顾问对桑德拉说：“你可以接着贷款。”于是桑德拉想到她还没有支付电费账单，便说：“你说的没错，我的确有这个需要。”</p><p>桑德拉就这样拉起来一条贷款链条。第二个月也不比第一个月轻松。她手头可以周转的钱变得更少了。因为需要支付手续费，所以她签下的贷款数额变得越来越大。接下来的几个月中，她不断去贷款，然后再用新的贷款来偿付之前的贷款。有的月份，她甚至连手续费都支付不起。</p><p>几次延期还款之后，第一位借款商提出了贷款全额偿付的要求。桑德拉没有能力偿还，于是找到了另一家工薪日贷款商“急钱服务公司”，贷了一笔钱，以偿还第一位贷款商的贷款。就这样，她越陷越深。短短6个月时间，桑德拉就要同时为6笔不同的工薪日贷款支付滞纳金。桑德拉和她丈夫差点就被房东从他们居住了6年的公寓中驱逐出去。桑德拉写道：“我们就是在用一笔贷款偿还另一笔贷款，后来手续费涨到了每个月495～600美元，我们就只能支付手续费，再没有能力偿还本金了。”</p><p>这种情况一直持续了至少6个月时间。这些钱并不能让夫妻俩过上奢侈的生活。桑德拉说：“人们总觉得你是挥霍无度才去借钱的。”但她并没有用这些钱买衣服，而是在支付账单。一直以来，桑德拉都勤勤恳恳，在艰难的吃日子里努力管理着家庭的收支。</p><p>后来，桑德拉的支票开始被退回，汽车也被收回了。她提高了免税额度，这样就能有多一点的钱去支付账单，结果却欠下了数千美元的退缴税。最后她破产了。在广播电台值班的时候，她总在休息时悄悄的擦眼泪。</p><p>“我不是一个轻易掉眼泪的人。”桑德拉说。</p></blockquote><p>这个故事来自《稀缺》发生在2006年的美国。</p><blockquote><p>调查数据显示，桑德拉的情况非常典型。2006年，全美共有23000多家工薪日贷款的分支机构，笔全部麦当劳（12000家）和星巴克（差不多9000家）加在一起还要多。桑德拉延期偿还贷款，积压手续费的这类行为也十分常见。所有工薪日贷款的3/4都来自延期偿付，最终形成了每年高达35亿美元的手续费。</p></blockquote><p>而2015年统计说，70%的美国人储蓄少于1000美元。这么看来，这样的故事，每天还在发生。</p><p>中国人民向来比较重视储蓄，但经过这么多年的超前消费的影响，而且2020年公布的数据说，6亿人的平均月收入为1000元左右。于是最近几年，我们会听到不少网贷事件，有的甚至比桑德拉的故事还更惨烈。</p><p>笑来老师说，在这个时代里，对年轻人最有价值的建议是这一条：“不要借钱消费！”</p><p>我们听过苦口婆心的说法，各类贷款，信用卡，X呗的利息（或者手续费）是很高的，没用，没人听。</p><p>如果正确理解资金的流向，我们就能更好的控制自己的借钱消费欲望，避免透支自己的未来。</p><p><img src="'+s+'" alt="资金流向"></p><hr><p>欢迎联系我</p><p>微信号 ：Crazy_Airhead</p><p>Mixin ID : 1091586</p><p>定投课堂邀请码：6DYMBFP061</p><p>李笑来写作课邀请码：38MDGFYZK8</p><p>水龙头邀请码：FDJQHJ</p>',17)])])}const u=t(n,[["render",c]]);export{m as __pageData,u as default};
